package com.hrms.office.controller;
import com.hrms.auth.security.AuthPrincipal;import com.hrms.common.responses.*;import com.hrms.office.dto.*;import com.hrms.office.model.OfficeStatus;import com.hrms.office.repository.*;import com.hrms.office.service.OfficeLocationService;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/office-locations") @Tag(name="Office locations") @SecurityRequirement(name="bearerAuth") @PreAuthorize("hasRole('ADMIN')")
public class OfficeLocationController {private final OfficeLocationService service;private final ClockSource clock;public OfficeLocationController(OfficeLocationService s,ClockSource c){service=s;clock=c;}
 @PostMapping public ApiResponse<OfficeLocationResponse> create(@Valid @RequestBody CreateOfficeLocationRequest r,@AuthenticationPrincipal AuthPrincipal a){return ApiResponse.success("Office location created",service.create(r,a),clock);}
 @GetMapping public ApiResponse<OfficeLocationPageResponse> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int limit,@RequestParam(required=false)String search,@RequestParam(required=false)OfficeStatus status,@RequestParam(defaultValue="createdAt")String sortBy,@RequestParam(defaultValue="desc")String sortDirection){return ApiResponse.success("Office locations retrieved",service.list(new OfficeSearch(search,status,page,limit,sortBy,sortDirection)),clock);}
 @GetMapping("/{id}") public ApiResponse<OfficeLocationResponse> get(@PathVariable String id){return ApiResponse.success("Office location retrieved",service.get(id),clock);}
 @PatchMapping("/{id}") public ApiResponse<OfficeLocationResponse> update(@PathVariable String id,@Valid @RequestBody UpdateOfficeLocationRequest r,@AuthenticationPrincipal AuthPrincipal a){return ApiResponse.success("Office location updated",service.update(id,r,a),clock);}
 @PatchMapping("/{id}/deactivate") public ApiResponse<OfficeLocationResponse> deactivate(@PathVariable String id,@AuthenticationPrincipal AuthPrincipal a){return ApiResponse.success("Office location deactivated",service.deactivate(id,a),clock);}
 @PatchMapping("/{id}/reactivate") public ApiResponse<OfficeLocationResponse> reactivate(@PathVariable String id,@AuthenticationPrincipal AuthPrincipal a){return ApiResponse.success("Office location reactivated",service.reactivate(id,a),clock);}}
